<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\UserRoleAssignamentRolesListRef;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\UserRoleAssignamentRolesUidVO;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\UserRoleAssignamentRolesRoleVO;
use Civi\Lughauth\Features\Access\Role\Domain\RoleRef;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\UserRoleAssignamentRolesVersionVO;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\UserRoleAssignamentRolesItem;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\ValueObject\Accessor\UserRoleAssignamentRolesAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserRoleAssignamentRolesAccessor trait.
 *
 * Covers null default, string/VO assignment via withRoles,
 * getRoles/roles accessors, and isRolesChanged with/without original.
 */
class UserRoleAssignamentRolesAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRoles creates a new instance with the Roles set
     * from a string value, and getRoles returns the primitive string.
     */
    public function testWithRolesFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserRoleAssignamentRolesAccessorUnitTest();

        // Act
        $result = $holder->withRoles(new UserRoleAssignamentRolesListRef( new UserRoleAssignamentRolesItem(
        UserRoleAssignamentRolesUidVO::from( 'one'),
        UserRoleAssignamentRolesRoleVO::from( new RoleRef('one')),
        UserRoleAssignamentRolesVersionVO::from( 1)
) ));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new UserRoleAssignamentRolesListRef( new UserRoleAssignamentRolesItem(
        UserRoleAssignamentRolesUidVO::from( 'one'),
        UserRoleAssignamentRolesRoleVO::from( new RoleRef('one')),
        UserRoleAssignamentRolesVersionVO::from( 1)
) ), $result->getRoles());
    }
    /**
     * Asserts that withroles has access to the value object
     * from a string value, and getRoles returns the primitive string.
     */
    public function testWithRolesFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserRoleAssignamentRolesAccessorUnitTest();

        // Act
        $result = $holder->withRoles(new UserRoleAssignamentRolesListRef( new UserRoleAssignamentRolesItem(
        UserRoleAssignamentRolesUidVO::from( 'one'),
        UserRoleAssignamentRolesRoleVO::from( new RoleRef('one')),
        UserRoleAssignamentRolesVersionVO::from( 1)
) ));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new UserRoleAssignamentRolesListRef( new UserRoleAssignamentRolesItem(
        UserRoleAssignamentRolesUidVO::from( 'one'),
        UserRoleAssignamentRolesRoleVO::from( new RoleRef('one')),
        UserRoleAssignamentRolesVersionVO::from( 1)
) ), $result->roles()->value());
    }
    public function testChangedRoles(): void
    {
        // Arrange
        $holder = new ImplWithUserRoleAssignamentRolesAccessorUnitTest()->withRoles(new UserRoleAssignamentRolesListRef( new UserRoleAssignamentRolesItem(
        UserRoleAssignamentRolesUidVO::from( 'one'),
        UserRoleAssignamentRolesRoleVO::from( new RoleRef('one')),
        UserRoleAssignamentRolesVersionVO::from( 1)
) ));
        $original = $holder->withRoles( new UserRoleAssignamentRolesListRef( new UserRoleAssignamentRolesItem(
        UserRoleAssignamentRolesUidVO::from( 'one'),
        UserRoleAssignamentRolesRoleVO::from( new RoleRef('one')),
        UserRoleAssignamentRolesVersionVO::from( 1)
) ));
        $same = $holder->withRoles( new UserRoleAssignamentRolesListRef( new UserRoleAssignamentRolesItem(
        UserRoleAssignamentRolesUidVO::from( 'one'),
        UserRoleAssignamentRolesRoleVO::from( new RoleRef('one')),
        UserRoleAssignamentRolesVersionVO::from( 1)
) ));
        $modified = $holder->withRoles(new UserRoleAssignamentRolesListRef( new UserRoleAssignamentRolesItem(
        UserRoleAssignamentRolesUidVO::from( 'other'),
        UserRoleAssignamentRolesRoleVO::from( new RoleRef('other')),
        UserRoleAssignamentRolesVersionVO::from( 2)
) ));

        // Act
        $withSame = $original->isRolesChanged( $same );
        $withDiferent = $original->isRolesChanged( $modified );

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserRoleAssignamentRolesAccessorUnitTest
{
  use UserRoleAssignamentRolesAccessor;
}
